import csv

# Get valid stop_ids from clean_stops.csv
valid_stop_ids = set()
with open('outputs/t05_clean_stops.csv', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        valid_stop_ids.add(row['stop_id'])

# Check stop_times.csv
invalid_stop_ids = set()
with open('outputs/t05_clean_stop_times.csv', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['stop_id'] not in valid_stop_ids:
            invalid_stop_ids.add(row['stop_id'])

if invalid_stop_ids:
    print(f'Found {len(invalid_stop_ids)} stop_ids in stop_times that are not in clean_stops:')
    for sid in sorted(invalid_stop_ids)[:10]:
        print(f'  {sid}')
else:
    print('All stop_ids in stop_times are present in clean_stops')
